"""LLM controls strength of a causal dense-error memory correction, with numeric controls."""
from common import *
from hybrid_router import KNOWLEDGE,descriptor
from concurrent.futures import ThreadPoolExecutor,as_completed
import sys

def run(level,part,thinking=False):
 name=f'20261105_mempolicy_l{level}_{part}_think{int(thinking)}_mse';out=ROOT/'runs'/name;out.mkdir(exist_ok=True);(out/'requests').mkdir(exist_ok=True)
 subprocess.run([sys.executable,str(ROOT/'src/preflight.py'),'--root',str(ROOT),'--run-name',name],check=True)
 cfg={'engine':'memory_policy_v1','level':level,'part':part,'thinking':thinking,'strength_choices':[0,.25,.5,.75],'fallback':.25,'cadence':24,'code_revision':git_head(),'memory_parent':'20261105_densememory_xbphase_mse','numeric_parent':'equal DLinear/Chronosavg/TimesFMavg'};save_json(out/'config.json',cfg)
 z=np.load(RUN/'cache/trainval_z.npy');manifest=json.loads((RUN/'cache/window_manifest.json').read_text());ca=np.load(RUN/'cache/dense_chronos_train.npz');ta=np.load(RUN/'cache/dense_timesfm_train.npz');origins=ca['origins'];tx,ty=windows(z[:8640],origins);tp=np.stack([ca['predictions'],ta['predictions']],1);err=ty[:,None]-tp;row={int(t):i for i,t in enumerate(origins)};neigh=json.loads((ROOT/'runs/20261105_densememory_xbphase_mse/neighbor_origins.json').read_text());cards=json.loads((ROOT/'src/knowledge_cards_v2.json').read_text())['facts'];results={};start=time.time()
 for split in (('dev','confirm') if part=='screen' else ('val',)):
  ts=manifest[split];d=np.load(RUN/'cache'/f'{split}_dlinear.npy');c=np.load(RUN/'cache'/f'{split}_chronosavg.npy');tf=np.load(RUN/'cache'/f'{split}_timesfmavg.npy');prior=(d+c+tf)/3;corrected=np.load(ROOT/'runs/20261105_densememory_xbphase_mse'/f'{split}_predictions.npy');unit=(corrected-prior)*4;alpha=np.full((len(ts),7),.25);records=[];step=24 if split=='val' else 1
  def one(i):
   guard(900);t=ts[i];x=z[t-512:t];ids=[row[int(v)] for v in neigh[split][i]];assert all(origins[j]+64<=t-512 for j in ids);res=err[ids].mean(1);bias=res.mean(1);std=np.maximum(x.std(0),.05)
   info={'columns':COLS,'prior':'equal DLinear, Chronos2 quantile average, TimesFM3 quantile average','memory_count':len(ids),'strength_default':.25,'history_mean24_96_512':[x[-k:].mean(0).round(3).tolist() for k in (24,96,512)],'history_std':std.round(3).tolist(),'history_change24':(x[-24:].mean(0)-x[-48:-24].mean(0)).round(3).tolist(),'acf24':[round(float(np.corrcoef(x[:-24,j],x[24:,j])[0,1]),3) if x[:,j].std()>1e-8 else 0 for j in range(7)],'proposed_unit_memory_shift_mean':unit[i].mean(0).round(3).tolist(),'proposed_unit_memory_shift_std':unit[i].std(0).round(3).tolist(),'memory_bias_mean':bias.mean(0).round(3).tolist(),'memory_bias_std':bias.std(0).round(3).tolist(),'memory_positive_bias_fraction':(bias>0).mean(0).round(3).tolist(),'forecast_mean_vs_recent96':(prior[i].mean(0)-x[-96:].mean(0)).round(3).tolist(),'tool_mean_disagreement':np.stack([d[i].mean(0),c[i].mean(0),tf[i].mean(0)]).std(0).round(3).tolist()}
   system='Choose per-variable strength for a fixed train-only error memory correction to minimize64-hour squared prediction error. Return ONLY JSON {"strength":[7 numbers each exactly one of0,.25,.5,.75]}. Forecast=prior+strength*unit_memory_correction. Default strength .25. Correction is computed by fixed numeric tools using8 non-overlapping nearest training cases, matching history and forecast descriptors, aligning errors by24-hour phase. No future observation or current error is given. Memory error sign is ACTUAL MINUS PREDICTED. Positive correction raises forecasts. Cases describe frozen pretrained Chronos/TimesFM only, not DLinear or current truth. Pretraining overlap not fully audited. Correlated regimes and eight-case uncertainty can make errors fail to transfer. Favor default unless concrete evidence supports change; signs alone do not establish transfer. You choose coefficients, not raw predictions. Strength is held for24 rolling origins on validation while numeric forecasts update hourly.'
   if level>=1:system+='\n'+KNOWLEDGE
   if level>=2:
    wanted={'ETT_FIELDS','NEGATIVE_RECORDED_VALUES','LEVEL_VS_CHANGE','CHANNEL_SPECIFIC_SEASONALITY','TRAIN_SOFT_BALANCE','THERMAL_LAG','COMMON_ZERO_RUN'};info['retrieved_knowledge_cards']=[v for v in cards if v['id'] in wanted];info['episodic_cases']=[{'origin':int(origins[j]),'mean_error':res[k].mean(0).round(3).tolist(),'early16_error':res[k,:16].mean(0).round(3).tolist(),'late16_error':res[k,-16:].mean(0).round(3).tolist(),'history_mean_difference':(tx[j].mean(0)-x.mean(0)).round(3).tolist()} for k,j in enumerate(ids)];system+=' Examine whether case agreement survives history-level mismatch and whether thermal/seasonal statements are observations or assumptions. Do not enforce physical equalities or guessed units. Return the seven strengths only after this check.'
   msgs=[{'role':'system','content':system},{'role':'user','content':json.dumps(info,separators=(',',':'),ensure_ascii=False)}];prefix=f'{split}_{i:04d}';save_json(out/'requests'/(prefix+'.json'),msgs)
   try:
    ans=api(msgs,10000 if thinking else 500,thinking='enabled' if thinking else 'disabled',reasoning_effort='low' if thinking else None);save_json(out/'requests'/(prefix+'_response.json'),ans);a=np.asarray(parse_json(ans['content'])['strength'],float);assert a.shape==(7,) and np.isfinite(a).all() and np.isin(a,[0,.25,.5,.75]).all();status='ok'
   except Exception as e:a=np.full(7,.25);status='fallback_'+type(e).__name__
   return i,a,status
  with ThreadPoolExecutor(max_workers=4) as pool:
   for f in as_completed([pool.submit(one,i) for i in range(0,len(ts),step)]):
    i,a,status=f.result();alpha[i:i+step]=a;records.append({'index':i,'origin':ts[i],'status':status});print(name,split,i,status,flush=True)
  p=(prior+alpha[:,None]*unit).astype(np.float32);m=metric(p,np.load(RUN/'cache'/f'{split}_targets.npy'));m['fallback_decisions']=sum(r['status']!='ok' for r in records);m['decisions']=len(records);results[split]=m;np.save(out/f'{split}_predictions.npy',p);np.save(out/f'{split}_strength.npy',alpha);save_json(out/f'{split}_decisions.json',records);save_json(out/'partial_metrics.json',results)
 save_json(out/'metrics.json',{'candidate':name,'metrics':results,'status':'evaluated','elapsed_seconds':time.time()-start});print(name,{s:m['mse'] for s,m in results.items()},flush=True)
if __name__=='__main__':run(int(sys.argv[1]),sys.argv[2],bool(int(sys.argv[3])) if len(sys.argv)>3 else False)
